args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>

SELECT ?prop ?father WHERE {
  VALUES ?prop { dbp:father dbo:father dbo:parent dbp:parent }
  <http://dbpedia.org/resource/Louis_VIII,_Landgrave_of_Hesse-Darmstadt> ?prop ?father .
}

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>

SELECT ?prop ?paternalGrandmother WHERE {
  VALUES ?prop { dbp:mother dbo:mother dbo:parent dbp:parent }
  <http://dbpedia.org/resource/Ernest_Louis,_Landgrave_of_Hesse-Darmstadt> ?prop ?paternalGrandmother .
}

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>

SELECT DISTINCT ?paternalGrandmother WHERE {
  VALUES ?parentprop { dbp:father dbo:father dbo:parent dbp:parent }
  VALUES ?motherprop { dbp:mother dbo:mother dbo:parent dbp:parent }

  <http://dbpedia.org/resource/Louis_VIII,_Landgrave_of_Hesse-Darmstadt> ?parentprop ?father .
  ?father ?motherprop ?paternalGrandmother .
  FILTER(isIRI(?paternalGrandmother))
}

